/// One coin's price history, as the price screen needs it.
///
/// `high` and `low` are over the series returned, so they describe exactly
/// what is drawn rather than some other window. `volume24h` is a day's
/// trading whatever the range, which is why it is named for the day.
typedef PriceHistory = ({
  List<double> series,
  double spanHours,
  int from,
  int to,
  double? high,
  double? low,
  double? volume24h,
  String source,
});

class PriceAPI {
  // coingecko coin ids
  static const Map<Type, String> _coinToIdMap = {
    Bitcoin: "bitcoin",
    BitcoinFrost: "bitcoin",
    Litecoin: "litecoin",
    Bitcoincash: "bitcoin-cash",
    Cardano: "cardano",
    Dash: "dash",
    Dogecoin: "dogecoin",
    Pepecoin: "pepecoin-network",
    Bellscoin: "bellscoin",
    Epiccash: "epic-cash",
    Mimblewimblecoin: "mimblewimblecoin",
    Ecash: "ecash",
    Ethereum: "ethereum",
    Fact0rn: "fact0rn",
    Firo: "zcoin",
    Monero: "monero",
    Particl: "particl",
    Peercoin: "peercoin",
    Solana: "solana",
    Stellar: "stellar",
    Tezos: "tezos",
    Wownero: "wownero",
    Namecoin: "namecoin",
    Nano: "nano",
    Banano: "banano",
    Xelis: "xelis",
    Salvium: "salvium",
  };

  static const refreshInterval = 60;

  // initialize to older than current time minus at least refreshInterval
  static DateTime _lastCalled = DateTime.now().subtract(
    const Duration(seconds: refreshInterval + 10),
  );

  static String _lastUsedBaseCurrency = "";

  static const Duration refreshIntervalDuration = Duration(
    seconds: refreshInterval,
  );

  final HTTP client;

  PriceAPI(this.client);

  @visibleForTesting
  void resetLastCalledToForceNextCallToUpdateCache() {
    _lastCalled = DateTime(1970);
  }

  Future<void> _updateCachedPrices(
    Map<CryptoCurrency, ({Decimal value, double change24h})> data,
  ) async {
    final Map<String, dynamic> map = {};

    for (final coin in AppConfig.coins) {
      final entry = data[coin];
      if (entry == null) {
        map[coin.prettyName] = ["0", 0.0];
      } else {
        map[coin.prettyName] = [entry.value.toString(), entry.change24h];
      }
    }

    await DB.instance.put<dynamic>(
      boxName: DB.boxNamePriceCache,
      key: 'cache',
      value: map,
    );
  }

  Map<CryptoCurrency, ({Decimal value, double change24h})> get _cachedPrices {
    final map =
        DB.instance.get<dynamic>(boxName: DB.boxNamePriceCache, key: 'cache')
            as Map? ??
        {};
    // init with 0
    final Map<CryptoCurrency, ({Decimal value, double change24h})> result = {};

    for (final entry in map.entries) {
      result[AppConfig.getCryptoCurrencyByPrettyName(entry.key as String)] = (
        value: Decimal.parse(entry.value[0] as String),
        change24h: entry.value[1] as double,
      );
    }

    return result;
  }

  String get _coinIds => AppConfig.coins
      .where((e) => e.network == CryptoCurrencyNetwork.main)
      .map((e) => _coinToIdMap[e.runtimeType])
      .where((e) => e != null)
      .join(",");

  /// 7-day hourly price series per coin, from the same markets response.
  /// Absent for any coin the price API does not list — BFX has no market, so it
  /// has no series, and the UI must render nothing rather than an empty chart.
  final Map<CryptoCurrency, List<double>> sparklines = {};

  /// What each sparkline ACTUALLY spans, in hours.
  ///
  /// CoinGecko's is always 168, because `sparkline_in_7d` is seven days by
  /// definition. BFX's is however much history its market has: 29 hours on the
  /// day it opened, growing. Deriving the spacing from the range the caller
  /// asked for instead of from this is how a 29-hour chart ends up labelling
  /// its oldest point "7d ago".
  final Map<CryptoCurrency, double> sparklineSpanHours = {};

  // Redesign: the hero chart gained 24H/30D ranges beside the bundled 7D
  // sparkline. Those need their own market_chart call, fetched lazily on
  // first selection and cached per coin+range+currency, because CoinGecko's
  // free tier rate-limits hard and the price poll already runs every minute.
  final Map<String, (DateTime, List<double>)> _marketChartCache = {};
  static const _marketChartCacheLife = Duration(minutes: 5);

  Future<List<double>?> getMarketChart({
    required CryptoCurrency coin,
    required int days,
    required String baseCurrency,
  }) async {
    final id = _coinToIdMap[coin.runtimeType];
    if (id == null) return null;

    final key = "$id:$days:${baseCurrency.toLowerCase()}";
    final cached = _marketChartCache[key];
    if (cached != null &&
        DateTime.now().difference(cached.$1) < _marketChartCacheLife) {
      return cached.$2;
    }

    try {
      final uri = Uri.parse(
        "https://api.coingecko.com/api/v3/coins/$id/market_chart"
        "?vs_currency=${baseCurrency.toLowerCase()}&days=$days",
      );

      final response = await client.get(
        url: uri,
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final json = jsonDecode(response.body);
      final prices = json["prices"] as List?;
      if (prices != null && prices.length > 1) {
        final series = prices
            .map((e) => ((e as List)[1] as num).toDouble())
            .toList(growable: false);
        _marketChartCache[key] = (DateTime.now(), series);
        return series;
      }
    } catch (e, s) {
      Logging.instance.w(
        "getMarketChart($id, $days) failed",
        error: e,
        stackTrace: s,
      );
    }
    // A stale series beats an empty chart flash on a transient failure.
    return cached?.$2;
  }

  // Price history for the price screen, from our own endpoint rather than
  // CoinGecko directly.
  //
  // Same three reasons the BFX price is proxied, now applied to every coin
  // the wallet ships: one server absorbs the source's rate limit instead of
  // every installation hitting it, a source change is a server fix rather
  // than an app release, and no third party gets a view of who runs this
  // wallet. It also carries the high, low and traded volume, which the
  // CoinGecko call below does not.
  //
  // Coins the endpoint does not know fall back to [getMarketChart], so a
  // coin added to the app before it is added to the server still charts.
  static const _historyUrl =
      "https://explorer.bitfinitechain.org/api/prices/history";

  /// Keyed on prettyName, matched exactly, because that is what distinguishes
  /// Bitcoin from Bitcoin Cash and a mainnet coin from its testnet twin. A
  /// test coin must never borrow a real market's price.
  static const _historyKeys = <String, String>{
    "BitFinite": "bfx",
    "Pepecoin": "pep",
    "Bellscoin": "bells",
    "Bitcoin": "btc",
    "Dogecoin": "doge",
  };

  final Map<String, (DateTime, PriceHistory)> _historyCache = {};

  /// True when the endpoint above can serve this coin at all.
  bool hasPriceHistory(CryptoCurrency coin) =>
      _historyKeys.containsKey(coin.prettyName);

  /// One coin's series over [days], with the figures that describe it.
  ///
  /// Null when the coin is not served, or nothing could be fetched and
  /// nothing was cached. A caller draws its empty state then; it must not
  /// draw a flat line through no data.
  Future<PriceHistory?> getPriceHistory({
    required CryptoCurrency coin,
    required int days,
    required String baseCurrency,
  }) async {
    final key = _historyKeys[coin.prettyName];
    if (key == null) return null;

    final currency = baseCurrency.toLowerCase();
    final cacheKey = "$key:$days:$currency";
    final cached = _historyCache[cacheKey];
    if (cached != null &&
        DateTime.now().difference(cached.$1) < _marketChartCacheLife) {
      return cached.$2;
    }

    try {
      final uri = Uri.parse("$_historyUrl?coin=$key&range=$days&vs=$currency");
      final response = await client.get(
        url: uri,
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final json = jsonDecode(response.body) as Map<String, dynamic>;
      final raw = json["series"] as List?;
      // Two points is the minimum that draws a line; one stretched across a
      // chart would be a flat claim about a market nobody measured.
      if (raw == null || raw.length < 2) return cached?.$2;

      double? num_(Object? v) {
        final d = (v as num?)?.toDouble();
        return d != null && d.isFinite && d > 0 ? d : null;
      }

      final out = (
        series: raw.map((e) => (e as num).toDouble()).toList(growable: false),
        // What the series really covers, which is not what was asked for:
        // the BFX market opened in September 2026, so a 30 day request
        // currently returns about 30 hours and a chart that labelled from
        // the range would date its oldest point a month back.
        spanHours: (json["spanHours"] as num?)?.toDouble() ?? days * 24.0,
        from: (json["from"] as num?)?.toInt() ?? 0,
        to: (json["to"] as num?)?.toInt() ?? 0,
        high: num_(json["high"]),
        low: num_(json["low"]),
        volume24h: num_(json["volume24h"]),
        source: (json["source"] as String?) ?? "",
      );
      _historyCache[cacheKey] = (DateTime.now(), out);
      return out;
    } catch (e, s) {
      Logging.instance.w(
        "getPriceHistory(${coin.prettyName}, $days) failed",
        error: e,
        stackTrace: s,
      );
    }
    // A stale series beats an empty chart on a transient failure.
    return cached?.$2;
  }

  // BFX ranges come from our own endpoint, not CoinGecko, for the same reason
  // its price does: CoinGecko does not list it. getMarketChart returns null
  // immediately for BFX (no id in the map), which is why 24H and 30D showed
  // nothing at all before this existed.
  final Map<String, (DateTime, ({List<double> series, double? spanHours}))>
  _bfxRangeCache = {};

  /// Price series for BFX over [days], or null when there is none.
  Future<({List<double> series, double? spanHours})?> getBitfiniteRange({
    required int days,
    required String baseCurrency,
  }) async {
    final key = "$days:${baseCurrency.toLowerCase()}";
    final cached = _bfxRangeCache[key];
    if (cached != null &&
        DateTime.now().difference(cached.$1) < _marketChartCacheLife) {
      return cached.$2;
    }

    final r = await _getBitfinitePrice(
      baseCurrency: baseCurrency,
      rangeDays: days,
    );
    // Two points is the minimum that draws a line. Below that, and on any
    // failure, a stale series beats an empty chart flash.
    if (r == null || r.sparkline.length < 2) return cached?.$2;

    final out = (series: r.sparkline, spanHours: r.spanHours);
    _bfxRangeCache[key] = (DateTime.now(), out);
    return out;
  }

  /// BFX price, from our own endpoint rather than CoinGecko.
  ///
  /// BFX is not on CoinGecko, so it was simply unpriced until it gained a
  /// market. This reads explorer.bitfinitechain.org, which proxies the
  /// exchange: the wallet polls every minute, and pointing every installation
  /// straight at the venue would hand it a view of our users.
  ///
  /// The endpoint quotes BFX/USDT and converts into whatever `vs` asks for, so
  /// this works for any base currency it knows. One it does not know returns
  /// 503 rather than a dollar figure wearing the wrong label, and we then show
  /// nothing, which is what the app did for BFX before it had a market at all.
  ///
  /// Returns null on any problem, which the caller treats as unpriced. Never
  /// returns zero: zero means "worthless" to every consumer downstream, and
  /// what we actually mean is "no price".
  static const _bfxPriceUrl = "https://explorer.bitfinitechain.org/api/price";

  Future<
    ({
      Decimal value,
      double change24h,
      List<double> sparkline,
      double? spanHours,
    })?
  >
  _getBitfinitePrice({required String baseCurrency, int rangeDays = 7}) async {
    final want = baseCurrency.toLowerCase().trim();
    try {
      final response = await client.get(
        url: Uri.parse("$_bfxPriceUrl?vs=$want&range=$rangeDays"),
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );
      if (response.code != 200) return null;

      final map = jsonDecode(response.body) as Map<String, dynamic>;

      // Check we got the currency we asked for. The endpoint states its own,
      // so a mismatch means something changed underneath us and the number
      // would be in the wrong units. Showing nothing beats showing that.
      if ((map["currency"] as String?)?.toLowerCase() != want) return null;

      final value = Decimal.tryParse(map["usd"].toString());
      if (value == null || value <= Decimal.zero) return null;

      // Absent until the market is genuinely a day old. The endpoint sends
      // null rather than dressing "change since listing" up as a 24h move.
      final change = (map["change24h"] as num?)?.toDouble() ?? 0.0;

      final series = (map["sparkline"] as List<dynamic>? ?? [])
          .map((e) => (e as num?)?.toDouble())
          .whereType<double>()
          .toList();

      // The endpoint states what its series really covers. An older server
      // that does not send it leaves this null, and the caller falls back to
      // assuming the range it asked for.
      final span = (map["spanHours"] as num?)?.toDouble();

      return (
        value: value,
        change24h: change,
        sparkline: series,
        spanHours: span,
      );
    } catch (e, s) {
      Logging.instance.e("_getBitfinitePrice: ", error: e, stackTrace: s);
      return null;
    }
  }

  Future<Map<CryptoCurrency, ({Decimal value, double change24h})>>
  getPricesAnd24hChange({required String baseCurrency}) async {
    final now = DateTime.now();
    if (_lastUsedBaseCurrency != baseCurrency ||
        now.difference(_lastCalled) > refreshIntervalDuration) {
      _lastCalled = now;
      _lastUsedBaseCurrency = baseCurrency;
    } else {
      return _cachedPrices;
    }

    final externalCalls = Prefs.instance.externalCalls;
    if ((!Util.isTestEnv && !externalCalls) ||
        !(await Prefs.instance.isExternalCallsSet())) {
      Logging.instance.i("User does not want to use external calls");
      return _cachedPrices;
    }
    final Map<CryptoCurrency, ({Decimal value, double change24h})> result = {};
    try {
      final uri = Uri.parse(
        "https://api.coingecko.com/api/v3/coins/markets?vs_currency"
        "=${baseCurrency.toLowerCase()}&ids=$_coinIds&order=market_cap_desc"
        "&per_page=50&page=1&sparkline=true",
        // sparkline=true costs no extra request: CoinGecko returns
        // sparkline_in_7d (168 hourly points) inside this same response.
        // It does make each response noticeably larger, which is why the
        // series is only read here and not polled on its own timer.
      );

      final coinGeckoResponse = await client.get(
        url: uri,
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final coinGeckoData = jsonDecode(coinGeckoResponse.body) as List<dynamic>;

      for (final map in coinGeckoData) {
        final String coinName = map["name"] as String;
        late CryptoCurrency coin;
        try {
          coin = AppConfig.getCryptoCurrencyByPrettyName(
            coinName == "Factor" ? "Fact0rn" : coinName,
          );
        } catch (e, s) {
          Logging.instance.e(
            "Failed to find matching app coin for $coinName. Moving on",
            error: e,
            stackTrace: s,
          );
          continue;
        }

        try {
          final price = Decimal.parse(map["current_price"].toString());
          final change24h = map["price_change_percentage_24h"] != null
              ? double.parse(map["price_change_percentage_24h"].toString())
              : 0.0;

          result[coin] = (value: price, change24h: change24h);

          // Kept in a separate map rather than widened into the record above:
          // that record's shape is depended on by 17 call sites, and none of
          // them want a price history.
          final spark = map["sparkline_in_7d"];
          if (spark is Map && spark["price"] is List) {
            final series = (spark["price"] as List)
                .map((e) => double.tryParse(e.toString()))
                .whereType<double>()
                .toList();
            if (series.length > 1) {
              sparklines[coin] = series;
              // sparkline_in_7d is seven days by definition.
              sparklineSpanHours[coin] = 168.0;
            } else {
              sparklines.remove(coin);
              sparklineSpanHours.remove(coin);
            }
          }
        } catch (_) {
          result.remove(coin);
          sparklines.remove(coin);
          sparklineSpanHours.remove(coin);
        }
      }

      // BFX rides alongside rather than inside the CoinGecko response,
      // because it is not listed there. A failure here must not lose the
      // prices we just fetched, so it is deliberately not inside the try
      // that wraps the CoinGecko call.
      final bfx = await _getBitfinitePrice(baseCurrency: baseCurrency);
      if (bfx != null) {
        try {
          // "BitFinite" with the capital F is the real prettyName, so this
          // matches on both the exact name and the lowercased identifier.
          // The testnet coin is "tBitFinite"/"bitfiniteTestnet" and cannot
          // collide with it.
          final coin = AppConfig.getCryptoCurrencyByPrettyName("BitFinite");
          result[coin] = (value: bfx.value, change24h: bfx.change24h);
          if (bfx.sparkline.length > 1) {
            sparklines[coin] = bfx.sparkline;
            if (bfx.spanHours != null) {
              sparklineSpanHours[coin] = bfx.spanHours!;
            } else {
              sparklineSpanHours.remove(coin);
            }
          } else {
            sparklines.remove(coin);
            sparklineSpanHours.remove(coin);
          }
        } catch (e, s) {
          Logging.instance.e(
            "BFX price: no matching app coin",
            error: e,
            stackTrace: s,
          );
        }
      }

      // update cache
      await _updateCachedPrices(result);

      return _cachedPrices;
    } catch (e, s) {
      Logging.instance.e(
        "getPricesAnd24hChange($baseCurrency): ",
        error: e,
        stackTrace: s,
      );
      // return previous cached values
      return _cachedPrices;
    }
  }

  static Future<List<String>?> availableBaseCurrencies() async {
    final externalCalls = Prefs.instance.externalCalls;
    const client = HTTP();

    if ((!Util.isTestEnv && !externalCalls) ||
        !(await Prefs.instance.isExternalCallsSet())) {
      Logging.instance.i("User does not want to use external calls");
      return null;
    }
    const uriString =
        "https://api.coingecko.com/api/v3/simple/supported_vs_currencies";
    try {
      final uri = Uri.parse(uriString);
      final response = await client.get(
        url: uri,
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final json = jsonDecode(response.body) as List<dynamic>;
      return List<String>.from(json);
    } catch (e, s) {
      Logging.instance.e(
        "availableBaseCurrencies() using $uriString: ",
        error: e,
        stackTrace: s,
      );
      return null;
    }
  }

